import { ref, onMounted, computed } from 'vue';
import { useI18n } from 'vue-i18n';
import { getQuryList } from '@/base/api/genflow'
import type { GenflowQueryItem } from '@/base/api/typings/genflow';
import GenflowInput from '../ai-home/components/main-content/genflow-input.vue';
import ArrowIcon from '@/assets/images/ai/ppt/new/arrow.png';

const { t: $t, locale } = useI18n();
const genflowModeList = ref<GenflowQueryItem[]>([]);
const currentModeIndex = ref(0);
const modeListLen = 3;
const activedModeList = computed(() => {
    if(currentModeIndex.value + modeListLen > genflowModeList.value.length) {
        return genflowModeList.value.slice(genflowModeList.value.length - modeListLen);   
    }
    return genflowModeList.value.slice(currentModeIndex.value, currentModeIndex.value + modeListLen);
})
const isCanPre = computed(() =>currentModeIndex.value > 0)
const isCanNext = computed(() => currentModeIndex.value + modeListLen < genflowModeList.value.length - 1)
async function initGenflowModeList () {
    const lang = locale.value;
    const list = await getQuryList({ lang });
    genflowModeList.value = list.items
}
initGenflowModeList();

function handlePreMode() {
    if (!isCanPre.value) {
        return;
    }
    currentModeIndex.value-=modeListLen;
}
function handleNextMode() {
    if (!isCanNext.value) {
        return;
    }
    currentModeIndex.value+=modeListLen;
}
</script>

